def canon(o):return json.dumps(o,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()
def sha(o):return hashlib.sha256(canon(o)).hexdigest()
def S(part,method,derivation,conclusion,checks,unresolved=None,assumptions=None):
 return dict(subpart_id=part,method=method,derivation=derivation,conclusion=conclusion,checks=checks,assumptions=assumptions or [],unresolved=unresolved or [])
